from repo.config import merge_config, old_merge_config
assert merge_config({'retries': 3, 'name': 'a'}, {'retries': 0, 'name': '', 'on': False, 'extra': None}) == {'retries': 0, 'name': '', 'on': False, 'extra': None}
assert merge_config({'a': 1}, {'a': 2, 'b': 3}) == {'a': 2, 'b': 3}
assert old_merge_config({'retries': 3}, {'retries': 0}) == {'retries': 0}
base = {'a': 1}
override = {'a': 0}
merge_config(base, override)
assert base == {'a': 1}
print('ok')
"

